    f.push(col(boxAt(1.9, 0.25, w, xf + face * 0.95, Y + 3.2, b.z), AWN[Math.floor(rnd() * AWN.length)]));
    const s = shopSlots[si++ % shopSlots.length], g = new THREE.PlaneGeometry(4.6, 1.15), [u0, v0, u1, v1] = atlas.rect(s), uv = g.attributes.uv;
